'use strict';

// A screen commit (build-screen) stays inside one slice's web/ folder, plus what composing it needs:
//
//   web/src/slices/{slice}/**    the slice's part: a form per command, a view per read model,
//                                handlers.ts (mock responses from its scenarios) and its tests
//   web/src/pages/*.tsx          the pages its screens are on (a page is shared by the slices on it)
//   web/src/lib/api-types.ts     regenerated by `npm run gen:api`, never edited by hand
//
// Nothing else: not the app shell, web/src/lib/, the mocks, the ui components or config, and no backend
// file (the backend step commits on its own). The slice's folder also needs a test.

const fs = require('fs');
const path = require('path');

const WEB_SLICE = /^web\/src\/slices\/([^/]+)\//;
const ALLOWED = [
  /^web\/src\/pages\/[^/]+\.tsx$/,     // page composition (a page file and its tests)
  /^web\/src\/lib\/api-types\.ts$/,   // generated client types
];

module.exports = {
  name: 'web-scope',
  scope: 'web',
  run(ctx) {
    const violations = [];
    const slices = new Set();
    for (const { path: p } of ctx.changes) {
      const m = p.match(WEB_SLICE);
      if (m) slices.add(m[1]);
    }
    const primary = [...slices].sort()[0];

    for (const { path: p } of ctx.changes) {
      const m = p.match(WEB_SLICE);
      if (m) {
        if (m[1] !== primary) {
          violations.push({ path: p, reason: `touches the screen of slice "${m[1]}" but this commit's scope is "${primary}" — split into separate commits` });
        }
        continue;
      }
      if (ALLOWED.some((r) => r.test(p))) continue;
      violations.push({
        path: p,
        reason: 'outside web/src/slices/{slice}/, the pages it composes (web/src/pages/*.tsx) and web/src/lib/api-types.ts — a screen commit changes nothing else',
      });
    }

    const dir = path.join(ctx.repoRoot, 'web/src/slices', primary);
    let files = [];
    try {
      files = fs.readdirSync(dir);
    } catch {
      return violations; // the folder is deleted in this commit
    }
    if (!files.some((f) => /\.test\.tsx?$/.test(f))) {
      violations.push({ path: `web/src/slices/${primary}/`, reason: 'no *.test.tsx: each form and view needs tests from the slice\'s scenarios' });
    }
    return violations;
  },
};
